-- Identity module (FR-1, FR-3, NFR-37, NFR-44, ADR-0005). IDs are random UUIDs generated by the application.

CREATE TABLE identity.account (
    id          uuid        PRIMARY KEY,
    status      text        NOT NULL DEFAULT 'ACTIVE'
                            CONSTRAINT account_status_valid
                            CHECK (status IN ('ACTIVE', 'DELETION_REQUESTED', 'ERASED')),
    first_name  text,
    created_at  timestamptz NOT NULL DEFAULT now()
);

-- One row per verified mobile number. Accounts are found ONLY by mobile_hash, never by mobile.
CREATE TABLE identity.mobile_identity (
    account_id   uuid        PRIMARY KEY REFERENCES identity.account (id),
    -- TODO(NFR-44): stored in plain text for the walking skeleton. It must be encrypted by the application
    -- before storage (key from a key management service). Lookups already use mobile_hash only, so only the
    -- storage of this column changes: add an encrypted column, backfill, switch the code, then drop this one.
    mobile       text        NOT NULL
                             CONSTRAINT mobile_identity_mobile_format
                             CHECK (mobile ~ '^\+91[6-9][0-9]{9}$'),
    -- HMAC-SHA256 of the normalised mobile number (NFR-44)
    mobile_hash  bytea       NOT NULL
                             CONSTRAINT mobile_identity_hash_length CHECK (octet_length(mobile_hash) = 32),
    verified_at  timestamptz NOT NULL,
    CONSTRAINT mobile_identity_hash_unique UNIQUE (mobile_hash)
);

-- One OTP challenge. The code is stored only as a keyed hash; attempts is capped at 5 by the database (NFR-37).
CREATE TABLE identity.otp_challenge (
    id          uuid        PRIMARY KEY,
    target_hash bytea       NOT NULL
                            CONSTRAINT otp_challenge_target_hash_length CHECK (octet_length(target_hash) = 32),
    code_hash   bytea       NOT NULL
                            CONSTRAINT otp_challenge_code_hash_length CHECK (octet_length(code_hash) = 32),
    purpose     text        NOT NULL
                            CONSTRAINT otp_challenge_purpose_valid CHECK (purpose IN ('LOGIN')),
    created_at  timestamptz NOT NULL DEFAULT now(),
    expires_at  timestamptz NOT NULL,
    attempts    smallint    NOT NULL DEFAULT 0
                            CONSTRAINT otp_challenge_attempts_range CHECK (attempts BETWEEN 0 AND 5),
    used_at     timestamptz,
    CONSTRAINT otp_challenge_expiry_after_creation CHECK (expires_at > created_at)
);

-- Finds the live challenges of a number (to supersede them on a new request)
CREATE INDEX otp_challenge_live_by_target ON identity.otp_challenge (target_hash) WHERE used_at IS NULL;

-- A login session. The refresh token is stored only as a hash and is replaced on every use (ADR-0005).
CREATE TABLE identity.session (
    id                  uuid        PRIMARY KEY,
    account_id          uuid        NOT NULL REFERENCES identity.account (id),
    refresh_token_hash  bytea       NOT NULL
                                    CONSTRAINT session_refresh_hash_length CHECK (octet_length(refresh_token_hash) = 32),
    created_at          timestamptz NOT NULL,
    last_used_at        timestamptz NOT NULL,
    revoked_at          timestamptz,
    CONSTRAINT session_refresh_hash_unique UNIQUE (refresh_token_hash),
    CONSTRAINT session_last_used_not_before_created CHECK (last_used_at >= created_at)
);

CREATE INDEX session_by_account ON identity.session (account_id);
